sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float density;
uniform float scale;
uniform float drift;
uniform float driftAngle;
uniform float layers;
uniform float heightBias;
uniform float contrast;
layout(color) uniform half4 fogColor;
uniform float softness;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(float2 p, float oct, float rough) {
    float v = 0.0;
    float a = 0.5;
    float norm = 0.0;
    for (int i = 0; i < 6; i++) {
        if (float(i) >= oct) break;
        v += a * vnoise(p);
        norm += a;
        p = p * 2.03 + float2(11.7, 5.3);
        a *= rough;
    }
    return v / max(norm, 0.0001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 dir = float2(cos(radians(driftAngle)), sin(radians(driftAngle)));
    float2 p = coord / max(scale, 1.0) + dir * time * drift;
    float n = fbm(p, 4.0, 0.5);
    if (layers > 1.5) n = mix(n, fbm(p * 1.9 - dir * time * drift * 0.6 + 7.1, 4.0, 0.5), 0.5);
    if (layers > 2.5) n = mix(n, fbm(p * 3.7 + dir * time * drift * 1.4 + 3.3, 3.0, 0.5), 0.35);
    n = saturate((n - 0.5) * contrast + 0.5);
    n = mix(n * n * (3.0 - 2.0 * n), n, softness);
    float h = mix(1.0, smoothstep(0.0, 1.0, coord.y / size.y), heightBias);
    float a = saturate(n * density * 2.0 * h);
    float3 o = mix(s, float3(fogColor.rgb), a);
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), opacity);
}
